examples.template:
ScrollView {
    MonarchWebhookDeliveries(
        deliveries: [
            MonarchWebhookDelivery(id: {{deliveries.0.id}}, status: {{deliveries.0.status}}, eventType: {{deliveries.0.eventType}}, eventID: {{deliveries.0.eventId}}, responseCode: {{deliveries.0.responseCode}}, durationMilliseconds: {{deliveries.0.durationMs}}, attempts: {{deliveries.0.attempts}}, date: Date(timeIntervalSinceNow: -{{deliveries.0.ageSeconds}})),
            MonarchWebhookDelivery(id: {{deliveries.1.id}}, status: {{deliveries.1.status}}, eventType: {{deliveries.1.eventType}}, eventID: {{deliveries.1.eventId}}, responseCode: {{deliveries.1.responseCode}}, error: {{deliveries.1.error}}, attempts: {{deliveries.1.attempts}}, date: Date(timeIntervalSinceNow: -{{deliveries.1.ageSeconds}}), nextAttempt: Date(timeIntervalSinceNow: {{deliveries.1.nextAttemptSeconds}})),
            MonarchWebhookDelivery(id: {{deliveries.2.id}}, status: {{deliveries.2.status}}, eventType: {{deliveries.2.eventType}}, eventID: {{deliveries.2.eventId}}, error: {{deliveries.2.error}}, attempts: {{deliveries.2.attempts}}, date: Date(timeIntervalSinceNow: -{{deliveries.2.ageSeconds}})),
            MonarchWebhookDelivery(id: {{deliveries.3.id}}, status: {{deliveries.3.status}}, eventType: {{deliveries.3.eventType}}, eventID: {{deliveries.3.eventId}}, attempts: {{deliveries.3.attempts}}, date: Date(timeIntervalSinceNow: -{{deliveries.3.ageSeconds}})),
        ],
        eventTypes: [{{eventTypes.0}}, {{eventTypes.1}}, {{eventTypes.2}}],
        onRedeliver: { _ in }
    )
    .padding()
}

examples.code:
ScrollView {
    MonarchWebhookDeliveries(
        deliveries: [
            MonarchWebhookDelivery(id: "d1", status: "succeeded", eventType: "order.created", eventID: "evt_3c91a0", responseCode: 200, durationMilliseconds: 142, attempts: 1, date: Date(timeIntervalSinceNow: -120)),
            MonarchWebhookDelivery(id: "d2", status: "retrying", eventType: "order.updated", eventID: "evt_3c8f12", responseCode: 503, error: "The endpoint answered 503", attempts: 2, date: Date(timeIntervalSinceNow: -540), nextAttempt: Date(timeIntervalSinceNow: 300)),
            MonarchWebhookDelivery(id: "d3", status: "failed", eventType: "invoice.paid", eventID: "evt_3c7b55", error: "No response within 10 seconds", attempts: 6, date: Date(timeIntervalSinceNow: -3900)),
            MonarchWebhookDelivery(id: "d4", status: "pending", eventType: "order.created", eventID: "evt_3c9d77", attempts: 0, date: Date(timeIntervalSinceNow: -30)),
        ],
        eventTypes: ["order.created", "order.updated", "invoice.paid"],
        onRedeliver: { _ in }
    )
    .padding()
}

